"""Remove duplicates from a sequence."""


def unique(items):
    """Return `items` without duplicates, first occurrence first."""
    result = []
    seen = set()
    for item in items:
        try:
            if item not in seen:
                seen.add(item)
                result.append(item)
        except TypeError:
            # Unhashable item (e.g. dict); compare by equality against
            # previously kept items.
            if item not in result:
                result.append(item)
    return result
